mockup.css:
.mock-section-figure-with-notes { background: #f0ede4; color: #181611; font-family: var(--f-sans); }
.mock-section-figure-with-notes .plate { position: absolute; inset: 11% 32% 11% 6%; }
.mock-section-figure-with-notes .note { position: absolute; inline-size: 23cqw; right: 5cqw;
  display: flex; flex-direction: column; gap: .5cqw; }
.mock-section-figure-with-notes .note b { font-family: var(--f-mono); font-size: 1.15cqw; letter-spacing: .14em; opacity: .5; }
.mock-section-figure-with-notes .note span { font-size: 1.4cqw; line-height: 1.45; }
.mock-section-figure-with-notes .note::before { content: ""; position: absolute; left: -6cqw; top: 1cqw;
  inline-size: 5cqw; block-size: 1px; background: currentColor; opacity: .38; }
.mock-section-figure-with-notes .n1 { top: 15%; }
.mock-section-figure-with-notes .n2 { top: 44%; }
.mock-section-figure-with-notes .n3 { top: 71%; }
